297	// ─────────────────────────────────────────── шкала оценки
298	
299	function renderEval(e) {
300	  if (!state || !state.settings.showEval) return;
301	  const cp = e.scoreCp ?? 0;
302	  // Логистическое отображение: линейное бесполезно, на нём интересный диапазон
303	  // ±80 сп неразличим, а ±1500 упирается в край.
304	  const p = e.mate !== null && e.mate !== undefined ? (e.mate > 0 ? 0.98 : 0.02) : 1 / (1 + Math.exp(-cp / 350));
305	  el.evalFill.style.height = `${(p * 100).toFixed(1)}%`;
306	  el.evalFill.style.width = `${(p * 100).toFixed(1)}%`;
307	  el.evalLabel.textContent =
308	    e.mate !== null && e.mate !== undefined ? `${e.mate < 0 ? '-' : ''}M${Math.abs(e.mate)}` : fmtCp(cp);
309	  el.evalbar.classList.toggle('shallow', (e.depth || 0) < 12);
310	}
