313	
314	const PHASE_TEXT = {
315	  baseline: 'АНАЛИЗ СЕКТОРА…',
316	  table: 'РАСЧЁТ ТРАЕКТОРИЙ…',
317	  screen: 'ОТБОР ВАРИАНТОВ ВЫСАДКИ…',
318	  verify: 'ПОДТВЕРЖДЕНИЕ НА ГЛУБИНЕ…',
319	};
320	
321	function showBanner(on) {
322	  el.banner.classList.toggle('on', on);
323	  if (on) {
324	    el.bannerBar.style.width = '0%';
325	    el.bannerPhase.textContent = PHASE_TEXT.baseline;
326	  }
327	}
328	
329	function renderProgress(p) {
330	  el.bannerPhase.textContent = `${PHASE_TEXT[p.phase] || p.phase} ${p.total > 1 ? `${p.done}/${p.total}` : ''}`;
331	  const weight = { baseline: 0.05, table: 0.2, screen: 0.55, verify: 1 };
332	  const base = { baseline: 0, table: 0.05, screen: 0.2, verify: 0.55 }[p.phase] ?? 0;
333	  const span = (weight[p.phase] ?? 1) - base;
334	  const inner = p.total > 0 ? p.done / p.total : 0;
335	  el.bannerBar.style.width = `${((base + span * inner) * 100).toFixed(0)}%`;
336	}
