339	
340	const PIP_LAYOUT = {
341	  1: [4],
342	  2: [0, 8],
343	  3: [0, 4, 8],
344	  4: [0, 2, 6, 8],
345	  5: [0, 2, 4, 6, 8],
346	  6: [0, 2, 3, 5, 6, 8],
347	};
348	
349	function drawDie(node, value) {
350	  node.innerHTML = '';
351	  const cells = PIP_LAYOUT[value] || [];
352	  for (let i = 0; i < 9; i++) {
353	    const cell = document.createElement('span');
354	    if (cells.includes(i)) {
355	      const pip = document.createElement('i');
356	      cell.appendChild(pip);
357	    }
358	    node.appendChild(cell);
359	  }
360	}
361	
362	function animateDice(roll, text) {
363	  el.diceText.textContent = '';
364	  el.die1.classList.add('rolling');
365	  el.die2.classList.add('rolling');
366	  const spin = setInterval(() => {
367	    drawDie(el.die1, 1 + Math.floor(Math.random() * 6));
368	    drawDie(el.die2, 1 + Math.floor(Math.random() * 6));
369	  }, 70);
370	  setTimeout(() => {
371	    clearInterval(spin);
372	    el.die1.classList.remove('rolling');
373	    el.die2.classList.remove('rolling');
374	    drawDie(el.die1, roll.d1);
375	    drawDie(el.die2, roll.d2);
376	    el.diceText.textContent = text;
377	  }, 700);
378	}
