381	
382	async function onMoveAttempt({ from, to }) {
383	  if (!state) return;
384	  // Превращение решает человек, а не сервер за него.
385	  const piece = state.board.find((p) => p.square === from);
386	  const lastRank = piece?.color === 'w' ? '8' : '1';
387	  if (piece?.type === 'p' && to[1] === lastRank) {
388	    pendingPromotion = { from, to };
389	    el.promo.classList.add('on');
390	    return;
391	  }
392	  await post('/api/move', { from, to, version: state.version });
393	}
