404	function fillSettings(s) {
405	  const sel = $('set-teller');
406	  if (sel.options.length === 0 && s.storytellers) {
407	    for (const t of s.storytellers) {
408	      const o = document.createElement('option');
409	      o.value = t.id;
410	      o.textContent = `${t.name} · ${t.codename}`;
411	      sel.appendChild(o);
412	    }
413	  }
414	  sel.value = s.settings.storyteller;
415	  $('teller-blurb').textContent = s.storytellers?.find((t) => t.id === sel.value)?.blurb || '';
416	  $('set-auto').value = s.settings.autoDropEveryFullMoves ?? '';
417	  $('set-rolls').value = s.settings.diceRollsPerPlayer;
418	  $('set-tol').value = s.settings.toleranceOverride ?? '';
419	  $('set-pieces').value = s.settings.pieceSet || 'xeno';
420	  $('set-badges').checked = s.settings.pieceBadges !== false;
421	  $('set-eval').checked = s.settings.showEval !== false;
422	  $('set-check').checked = s.settings.forbidCheckOnDrop !== false;
423	}
