425	async function pushSettings() {
426	  const num = (id) => ($(id).value === '' ? null : Number($(id).value));
427	  await post('/api/settings', {
428	    storyteller: $('set-teller').value,
429	    autoDropEveryFullMoves: num('set-auto'),
430	    diceRollsPerPlayer: Number($('set-rolls').value),
431	    toleranceOverride: num('set-tol'),
432	    pieceSet: $('set-pieces').value,
433	    pieceBadges: $('set-badges').checked,
434	    showEval: $('set-eval').checked,
435	    forbidCheckOnDrop: $('set-check').checked,
436	  });
437	}
