134	
135	  async handleMove(body) {
136	    const result = this.game.move({ from: body.from, to: body.to, promotion: body.promotion });
137	    if (!result.ok) return result;
138	    this.#broadcastState('move');
139	    this.#retarget();
140	
141	    // Автоматический десант приходит ПОСЛЕ хода чёрных, то есть на границе полного
142	    // хода: иначе одна из сторон систематически получала бы подкрепление первой.
143	    if (this.game.autoDropDue && !this.game.gameOver && !this.dropInProgress) {
144	      this.#runDrop({ trigger: 'auto' }).catch((err) => console.error('[десант]', err));
145	    } else {
146	      this.#maybeComputerMove();
147	    }
148	    return { ok: true, version: this.game.version };
149	  }
150	
151	  /** Сидит ли за этой стороной компьютер. */
152	  #isComputer(side) {
153	    const players = this.game.settings.players || {};
154	    return players[side] === 'computer';
155	  }
156	
157	  /**
158	   * Ход компьютера, если сейчас его очередь.
159	   *
160	   * Намеренно не await: ход считается в фоне, а состояние уезжает клиенту событием.
161	   * Иначе HTTP-ответ на ход человека ждал бы, пока движок додумает свой, и интерфейс
162	   * замирал бы на секунды без единого признака жизни.
163	   */
164	  #maybeComputerMove() {
165	    if (this.computerThinking || this.dropInProgress) return;
166	    if (this.game.gameOver || !this.#isComputer(this.game.turn)) return;
167	    if (!this.pool || !this.pool.healthy) return;
168	
169	    this.computerThinking = true;
170	    const side = this.game.turn;
171	    const versionAtStart = this.game.version;
172	    this.hub.emitVolatile('thinking', { side, level: getLevel(this.game.settings.computerLevel).name });
173	
174	    (async () => {
175	      try {
176	        const choice = await chooseComputerMove(this.pool, this.game.fen, {
177	          level: this.game.settings.computerLevel,
178	          rng: this.rng,
179	        });
180	        // Пока движок думал, партию могли отменить, начать заново или высадить десант.
181	        if (!choice || this.game.version !== versionAtStart) return;
182	        const r = this.game.move(choice);
183	        if (!r.ok) return;
184	        this.#broadcastState('move');
185	        this.#retarget();
186	        if (this.game.autoDropDue && !this.game.gameOver && !this.dropInProgress) {
187	          this.#runDrop({ trigger: 'auto' }).catch((err) => console.error('[десант]', err));
188	        }
189	      } catch (err) {
190	        console.error('[компьютер]', err.message);
191	      } finally {
192	        this.computerThinking = false;
193	        // Компьютер против компьютера: следующий ход запускается той же цепочкой.
194	        setTimeout(() => this.#maybeComputerMove(), 120);
195	      }
196	    })();
197	  }
198	
199	  async handleRoll(body) {
200	    const side = body.side === 'b' ? 'b' : 'w';
201	    if (this.dropInProgress) {
202	      return { ok: false, code: 'DROP_IN_PROGRESS', message: 'ВЫСАДКА УЖЕ ИДЁТ' };
203	    }
204	    if (this.game.gameOver) return { ok: false, code: 'GAME_OVER', message: 'ПАРТИЯ ОКОНЧЕНА' };
205	    if (this.game.turn !== side) return { ok: false, code: 'NOT_YOUR_TURN', message: 'СЕЙЧАС НЕ ВАШ ХОД' };
206	    if (this.game.dice[side] <= 0) return { ok: false, code: 'NO_TOKENS', message: 'БРОСКИ ЗАКОНЧИЛИСЬ' };
207	
208	    this.game.spendDiceRoll(side);
209	    const roll = interpretRoll(rollDice(this.rng), side);
210	    this.game.version += 1;
211	    this.hub.emit('dice', { roll, text: describeRoll(roll), dice: this.game.dice }, { id: this.game.version });
212	
213	    this.#runDrop({ trigger: 'dice', roll }).catch((err) => console.error('[десант]', err));
214	    return { ok: true, version: this.game.version, roll };
215	  }
216	
217	  async handleNewGame(body) {
218	    if (this.dropInProgress) return { ok: false, code: 'DROP_IN_PROGRESS', message: 'ВЫСАДКА УЖЕ ИДЁТ' };
219	    const settings = { ...this.game.settings, ...(body.settings || {}) };
220	    const seed = body.seed || `game-${Date.now()}`;
221	    // Расстановка Фишера берётся из того же сида, что и вся партия: одинаковый сид
222	    // даёт одинаковую стартовую позицию, и партию можно воспроизвести целиком.
223	    const startFen = settings.startPosition === 'fischer' ? fischerFen(makeRng(`fischer:${seed}`)) : undefined;
224	    this.game = new Game({ settings, seed, ...(startFen ? { fen: startFen } : {}) });
225	    this.rng = makeRng(seed);
226	    this.#broadcastState('snapshot');
227	    this.#retarget();
228	    this.#maybeComputerMove();
229	    return { ok: true, version: this.game.version };
230	  }
231	
232	  async handleUndo() {
233	    if (this.dropInProgress) return { ok: false, code: 'DROP_IN_PROGRESS', message: 'ВЫСАДКА УЖЕ ИДЁТ' };
234	    const r = this.game.undo();
235	    if (!r.ok) return r;
236	    this.#broadcastState('snapshot');
237	    this.#retarget();
238	    return { ok: true, version: this.game.version };
239	  }
240	
241	  async handleSettings(body) {
242	    const allowed = Object.keys(DEFAULT_SETTINGS);
243	    const next = { ...this.game.settings };
244	    for (const [k, v] of Object.entries(body || {})) {
245	      if (!allowed.includes(k)) continue;
246	      next[k] = v;
247	    }
248	    if (next.autoDropEveryFullMoves !== null) {
249	      next.autoDropEveryFullMoves = Math.max(0, Math.min(20, Number(next.autoDropEveryFullMoves) || 0));
250	    }
251	    next.diceRollsPerPlayer = Math.max(0, Math.min(9, Number(next.diceRollsPerPlayer) || 0));
252	    next.computerLevel = Math.max(1, Math.min(5, Number(next.computerLevel) || 3));
253	    const seats = next.players && typeof next.players === 'object' ? next.players : {};
254	    next.players = {
255	      w: seats.w === 'computer' ? 'computer' : 'human',
256	      b: seats.b === 'computer' ? 'computer' : 'human',
257	    };
258	    if (next.startPosition !== 'fischer') next.startPosition = 'standard';
259	    if (!getStoryteller(next.storyteller)) next.storyteller = 'bishop';
260	    this.game.settings = next;
261	    this.game.version += 1;
262	    this.#broadcastState('settings');
263	    this.#maybeComputerMove();
264	    return { ok: true, version: this.game.version, settings: next };
265	  }
266	
267	  /** Только для end-to-end проверок: поставить произвольную позицию. */
268	  async handleTestFen(body) {
269	    try {
270	      this.game = new Game({ fen: body.fen, settings: this.game.settings });
271	      this.rng = makeRng(this.game.seed);
272	      this.#broadcastState('snapshot');
273	      this.#retarget();
274	      return { ok: true, version: this.game.version };
275	    } catch (err) {
276	      return { ok: false, code: 'BAD_REQUEST', message: `НЕВЕРНАЯ ПОЗИЦИЯ: ${err.message}` };
277	    }
278	  }
279	
280	  // ─────────────────────────────────────────── десант
281	
282	  async #runDrop({ trigger, roll = null }) {
283	    if (this.dropInProgress) return;
284	    if (!this.pool || !this.pool.healthy) {
285	      this.hub.emit('drop:skipped', { reason: 'ДВИЖОК НЕДОСТУПЕН' }, { id: this.game.version });
286	      return;
287	    }
288	
289	    const id = this.game.dropLog.length + 1;
290	    this.dropInProgress = { id, phase: 'baseline', done: 0, total: 1, trigger };
291	    this.game.phase = 'dropping';
292	    this.dropAbort = new AbortController();
293	    this.#broadcastState('drop:start');
294	
295	    // Поиск десанта — приоритет по ядрам; шкала оценки на это время замолкает.
296	    await this.analysis?.pause();
297	
298	    try {
299	      const result = await generateBalancedDrop(this.pool, this.game.fen, {
300	        rng: this.rng,
301	        storytellerId: this.game.settings.storyteller,
302	        dice: roll,
303	        ledgerCp: this.game.ledgerCp,
304	        aggregateNps: this.aggregateNps,
305	        signal: this.dropAbort.signal,
306	        toleranceOverride: this.game.settings.toleranceOverride,
307	        dropOptions: {
308	          allowNearPromotion: this.game.settings.allowNearPromotion,
309	          forbidCheck: this.game.settings.forbidCheckOnDrop,
310	        },
311	        onProgress: (p) => {
312	          this.dropInProgress = { id, ...p, trigger };
313	          this.hub.emitVolatile('drop:progress', { id, ...p });
314	        },
315	      });
316	
317	      this.game.phase = 'idle';
318	      this.dropInProgress = null;
319	
320	      if (result.ok) {
321	        this.game.applyDrop(result);
322	        this.hub.emit(
323	          'drop:done',
324	          { drop: this.game.dropLog[this.game.dropLog.length - 1], state: this.snapshot() },
325	          { id: this.game.version },
326	        );
327	      } else {
328	        // Честный отказ лучше подделанного десанта: жетон возвращается,
329	        // а причина показывается игроку словами.
330	        if (trigger === 'dice' && roll) this.game.refundDiceRoll(roll.side);
331	        this.game.noteSkippedDrop(result.reason);
332	        this.hub.emit(
333	          'drop:skipped',
334	          { id, reason: result.reason, state: this.snapshot() },
335	          { id: this.game.version },
336	        );
337	      }
338	    } catch (err) {
339	      this.game.phase = 'idle';
340	      this.dropInProgress = null;
341	      if (trigger === 'dice' && roll) this.game.refundDiceRoll(roll.side);
342	      this.game.noteSkippedDrop(`сбой поиска: ${err.message}`);
343	      this.hub.emit('drop:skipped', { id, reason: `СБОЙ ПОИСКА: ${err.message}`, state: this.snapshot() }, { id: this.game.version });
344	    } finally {
345	      this.dropAbort = null;
346	      this.analysis?.resume(this.game.fen);
347	      this.#maybeComputerMove();
348	    }
349	  }
350	}
