356	  const engineInfo = useMock ? null : readJsonSafe(CURRENT_JSON);
357	  if (!useMock && !engineInfo) {
358	    console.error('Движок не установлен. Выполните:  npm run setup');
359	    process.exit(1);
360	  }
361	
362	  console.log('NOSTROMO GAMBIT');
363	  if (engineInfo) console.log(`  движок: ${engineInfo.uciName} (${engineInfo.kind})`);
