1	// Маршрутизатор на node:http. Никаких фреймворков — маршрутов девять.
2	import { createStaticHandler } from './static.mjs';
3	
4	const MAX_BODY = 64 * 1024;
5	
6	function readJson(req) {
7	  return new Promise((resolve, reject) => {
8	    let size = 0;
9	    const chunks = [];
10	    req.on('data', (c) => {
11	      size += c.length;
12	      if (size > MAX_BODY) {
13	        reject(new Error('слишком большое тело запроса'));
14	        req.destroy();
15	        return;
16	      }
17	      chunks.push(c);
18	    });
19	    req.on('end', () => {
20	      if (chunks.length === 0) return resolve({});
21	      try {
22	        resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')));
23	      } catch (err) {
24	        reject(err);
25	      }
26	    });
27	    req.on('error', reject);
28	  });
29	}
30	
31	function sendJson(res, status, payload) {
32	  const body = Buffer.from(JSON.stringify(payload), 'utf8');
33	  res.writeHead(status, {
34	    'Content-Type': 'application/json; charset=utf-8',
35	    'Content-Length': body.length,
36	    'Cache-Control': 'no-store',
37	  });
38	  res.end(body);
39	}
40	
41	/** Код ошибки -> HTTP-статус. Одна таблица вместо разбросанных чисел. */
42	const STATUS = {
43	  STALE_VERSION: 409,
44	  DROP_IN_PROGRESS: 409,
45	  GAME_OVER: 409,
46	  NO_TOKENS: 409,
47	  NOT_YOUR_TURN: 409,
48	  NOTHING_TO_UNDO: 409,
49	  ILLEGAL_MOVE: 422,
50	  PROMOTION_REQUIRED: 422,
51	  BAD_REQUEST: 400,
52	  ENGINE_UNAVAILABLE: 503,
53	};
54	
55	export function createRouter({ app, publicDir }) {
56	  const serveStatic = createStaticHandler(publicDir);
57	  const isTest = process.env.NODE_ENV === 'test';
58	
59	  return async function handle(req, res) {
60	    const url = new URL(req.url, 'http://127.0.0.1');
61	    const p = url.pathname;
62	
63	    try {
64	      if (req.method === 'GET' && p === '/api/state') {
65	        return sendJson(res, 200, app.snapshot());
66	      }
67	
68	      if (req.method === 'GET' && p === '/api/events') {
69	        app.attachEventStream(req, res);
70	        return undefined;
71	      }
72	
73	      if (req.method === 'GET' && p === '/health') {
74	        return sendJson(res, 200, app.health());
75	      }
76	
77	      if (req.method === 'POST') {
78	        let body;
79	        try {
80	          body = await readJson(req);
81	        } catch {
82	          return sendJson(res, 400, { ok: false, code: 'BAD_REQUEST', message: 'НЕЧИТАЕМЫЙ ЗАПРОС' });
83	        }
84	
85	        // Оптимистичная конкурентность: клиент сообщает версию, которую видел.
86	        // Расхождение означает, что он смотрит на устаревшее состояние.
87	        const needsVersion = ['/api/move', '/api/roll', '/api/undo'];
88	        if (needsVersion.includes(p) && body.version !== undefined && body.version !== app.game.version) {
89	          return sendJson(res, 409, {
90	            ok: false,
91	            code: 'STALE_VERSION',
92	            message: 'СОСТОЯНИЕ УСТАРЕЛО',
93	            version: app.game.version,
94	          });
95	        }
96	
97	        let result;
98	        if (p === '/api/move') result = await app.handleMove(body);
99	        else if (p === '/api/roll') result = await app.handleRoll(body);
100	        else if (p === '/api/new-game') result = await app.handleNewGame(body);
101	        else if (p === '/api/undo') result = await app.handleUndo(body);
102	        else if (p === '/api/settings') result = await app.handleSettings(body);
103	        else if (p === '/api/_test/fen' && isTest) result = await app.handleTestFen(body);
104	        else result = null;
105	
106	        if (result === null) {
107	          return sendJson(res, 404, { ok: false, code: 'NOT_FOUND', message: 'НЕТ ТАКОГО МАРШРУТА' });
108	        }
109	        if (!result.ok) {
110	          return sendJson(res, STATUS[result.code] || 400, result);
111	        }
112	        return sendJson(res, 200, result);
113	      }
114	
115	      if (req.method === 'GET' || req.method === 'HEAD') {
116	        const served = await serveStatic(req, res, p);
117	        if (served) return undefined;
118	      }
119	
120	      return sendJson(res, 404, { ok: false, code: 'NOT_FOUND', message: 'НЕ НАЙДЕНО' });
121	    } catch (err) {
122	      // Ошибку показываем, но не роняем сервер: партия должна пережить сбой.
123	      console.error('[http] необработанная ошибка:', err);
124	      if (!res.headersSent) {
125	        return sendJson(res, 500, { ok: false, code: 'INTERNAL', message: 'ВНУТРЕННЯЯ ОШИБКА СЕРВЕРА' });
126	      }
127	      return undefined;
128	    }
129	  };
130	}
