1	// Один мультиплексированный поток событий.
2	//
3	// Почему ровно один: HTTP/1.1 держит около шести соединений на origin. Два потока
4	// (оценка и прогресс десанта) на двух вкладках — это уже четыре из шести, а третья
5	// вкладка вешает приложение целиком. Поэтому все типы событий идут по одному
6	// маршруту и различаются полем `event:`.
7	//
8	// Волатильные события (оценка, прогресс) намеренно идут БЕЗ поля `id:`: иначе они
9	// отравляют Last-Event-ID и при переподключении браузер просит воспроизвести
10	// с той точки, где нет ни одного состояния.
11	
12	const RING_SIZE = 200;
13	const HEARTBEAT_MS = 15000;
14	
15	export class SseHub {
16	  #clients = new Set();
17	  #ring = [];
18	  #timer = null;
19	
20	  constructor({ sessionId }) {
21	    this.sessionId = sessionId;
22	  }
23	
24	  get clientCount() {
25	    return this.#clients.size;
26	  }
27	
28	  attach(req, res, { lastEventId = null, initial = null } = {}) {
29	    res.writeHead(200, {
30	      'Content-Type': 'text/event-stream; charset=utf-8',
31	      // no-transform обязателен: без него прокси и расширения вправе перепаковать
32	      // поток и склеить кадры.
33	      'Cache-Control': 'no-cache, no-transform',
34	      Connection: 'keep-alive',
35	      // Подсказка обратным прокси не буферизовать поток.
36	      'X-Accel-Buffering': 'no',
37	    });
38	    res.flushHeaders?.();
39	    // Без этого Nagle склеивает шестидесятибайтные кадры оценки в рывки по 40 мс.
40	    res.socket?.setNoDelay?.(true);
41	    res.write(`retry: 3000\n\n`);
42	
43	    const client = { res, alive: true };
44	    this.#clients.add(client);
45	
46	    const replayed = lastEventId !== null ? this.#replayFrom(Number(lastEventId), client) : false;
47	    if (!replayed && initial) this.#writeTo(client, initial);
48	
49	    req.on('close', () => {
50	      client.alive = false;
51	      this.#clients.delete(client);
52	    });
53	
54	    if (!this.#timer) this.#startHeartbeat();
55	    return client;
56	  }
57	
58	  #startHeartbeat() {
59	    this.#timer = setInterval(() => {
60	      for (const c of this.#clients) {
61	        try {
62	          c.res.write(': ping\n\n');
63	        } catch {
64	          this.#clients.delete(c);
65	        }
66	      }
67	    }, HEARTBEAT_MS);
68	    this.#timer.unref?.();
69	  }
70	
71	  /** Кадр состояния: несёт id и попадает в кольцевой буфер. */
72	  emit(event, data, { id = null } = {}) {
73	    const frame = { event, data, id };
74	    if (id !== null) {
75	      this.#ring.push(frame);
76	      if (this.#ring.length > RING_SIZE) this.#ring.shift();
77	    }
78	    for (const client of [...this.#clients]) this.#writeTo(client, frame);
79	  }
80	
81	  /** Кадр без id: оценка, прогресс, всё, что не является состоянием. */
82	  emitVolatile(event, data) {
83	    this.emit(event, data, { id: null });
84	  }
85	
86	  #writeTo(client, frame) {
87	    if (!client.alive) return;
88	    try {
89	      let payload = '';
90	      if (frame.id !== null && frame.id !== undefined) payload += `id: ${frame.id}\n`;
91	      payload += `event: ${frame.event}\n`;
92	      // Многострочные данные обязаны разбиваться на несколько строк data:,
93	      // иначе перевод строки внутри полезной нагрузки рвёт кадр.
94	      const body = JSON.stringify(frame.data);
95	      for (const line of body.split('\n')) payload += `data: ${line}\n`;
96	      payload += '\n';
97	      client.res.write(payload);
98	    } catch {
99	      client.alive = false;
100	      this.#clients.delete(client);
101	    }
102	  }
103	
104	  /** @returns {boolean} удалось ли воспроизвести хвост; false — нужен полный снимок. */
105	  #replayFrom(lastId, client) {
106	    if (!Number.isFinite(lastId)) return false;
107	    const idx = this.#ring.findIndex((f) => f.id > lastId);
108	    if (idx === -1) {
109	      // Либо клиент уже всё видел, либо ушёл слишком далеко — в обоих случаях
110	      // отдаём полный снимок, это дешевле и надёжнее любых догадок.
111	      return false;
112	    }
113	    if (this.#ring[0].id > lastId + 1) return false; // разрыв: часть событий уже вытеснена
114	    for (const frame of this.#ring.slice(idx)) this.#writeTo(client, frame);
115	    return true;
116	  }
117	
118	  close() {
119	    if (this.#timer) clearInterval(this.#timer);
120	    for (const c of this.#clients) {
121	      try {
122	        c.res.end();
123	      } catch {
124	        /* соединение уже закрыто */
125	      }
126	    }
127	    this.#clients.clear();
128	  }
129	}
