1	// Машина состояний партии.
2	//
3	// Главное решение этого файла продиктовано проверенной находкой: `chess.js` 1.4.0
4	// в `load()` вызывает `clear()` и стирает свою внутреннюю историю. Десант обязан
5	// пересобирать позицию из FEN, поэтому опираться на историю chess.js через десант
6	// нельзя — молча пропали бы отмена хода, список ходов и троекратное повторение.
7	//
8	// Поэтому Game ведёт СВОЙ журнал атомов (ход или десант) и стек снимков FEN,
9	// а chess.js используется только как генератор ходов для ТЕКУЩЕЙ позиции.
10	import { Chess } from 'chess.js';
11	import { materialBalance, countMaterial, freeSlots, squareName } from './fen.mjs';
12	import { getStoryteller, DEFAULT_STORYTELLER } from './storytellers.mjs';
13	
14	export const START_FEN = 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1';
15	
16	export const DEFAULT_SETTINGS = {
17	  storyteller: DEFAULT_STORYTELLER,
18	  /** Кто сидит за каждой стороной: 'human' или 'computer'. */
19	  players: { w: 'human', b: 'human' },
20	  computerLevel: 3,
21	  /** 'standard' или 'fischer' (расстановка 960, рокировка выключена). */
22	  startPosition: 'standard',
23	  /** 0 отключает автоматический десант. */
24	  autoDropEveryFullMoves: null, // null = взять из профиля планировщика
25	  diceRollsPerPlayer: 3,
26	  showEval: true,
27	  pieceSet: 'xeno', // 'xeno' | 'classic'
28	  pieceBadges: true,
29	  allowNearPromotion: false,
30	  forbidCheckOnDrop: true,
31	  toleranceOverride: null,
32	  seed: null,
33	};
34	
35	const GAME_OVER_TEXT = {
36	  checkmate: 'МАТ',
37	  stalemate: 'ПАТ',
38	  insufficient_material: 'НИЧЬЯ: НЕДОСТАТОЧНО МАТЕРИАЛА',
39	  threefold: 'НИЧЬЯ: ТРОЕКРАТНОЕ ПОВТОРЕНИЕ',
40	  fifty_move: 'НИЧЬЯ: ПРАВИЛО 50 ХОДОВ',
41	};
42	
43	let nextPieceId = 1;
44	
45	export class Game {
46	  constructor({ settings = {}, fen = START_FEN, seed = null } = {}) {
47	    this.settings = { ...DEFAULT_SETTINGS, ...settings };
48	    this.seed = seed || this.settings.seed || `game-${Date.now()}`;
49	    this.startFen = fen;
50	    this.reset(fen);
51	  }
52	
53	  reset(fen = START_FEN) {
54	    this.chess = new Chess(fen);
55	    this.version = 0;
56	    this.atoms = [];
57	    this.snapshots = [fen];
58	    this.dropLog = [];
59	    this.moveLog = [];
60	    this.dice = { w: this.settings.diceRollsPerPlayer, b: this.settings.diceRollsPerPlayer };
61	    this.ledgerCp = 0;
62	    this.movesSinceDrop = 0;
63	    this.consecutiveSkips = 0;
64	    this.phase = 'idle';
65	    this.gameOver = null;
66	    this.pieces = new Map(); // поле -> {id, type, color}
67	    for (const sq of this.#occupiedSquares()) {
68	      const p = this.chess.get(sq);
69	      this.pieces.set(sq, { id: `p${nextPieceId++}`, type: p.type, color: p.color });
70	    }
71	    this.#refreshGameOver();
72	    return this;
73	  }
74	
75	  #occupiedSquares() {
76	    const out = [];
77	    for (const row of this.chess.board()) {
78	      for (const cell of row) if (cell) out.push(cell.square);
79	    }
80	    return out;
81	  }
82	
83	  get fen() {
84	    return this.chess.fen();
85	  }
86	
87	  get turn() {
88	    return this.chess.turn();
89	  }
90	
91	  get storyteller() {
92	    return getStoryteller(this.settings.storyteller);
93	  }
94	
95	  /** Через сколько ходов сработает автоматический десант. 0 — прямо сейчас, null — выключен. */
96	  get movesUntilAutoDrop() {
97	    const every = this.settings.autoDropEveryFullMoves ?? this.storyteller.autoEveryFullMoves;
98	    if (!every || every <= 0) return null;
99	    return Math.max(0, every - this.movesSinceDrop);
100	  }
101	
102	  get autoDropDue() {
103	    const left = this.movesUntilAutoDrop;
104	    return left === 0;
105	  }
106	
107	  // ───────────────────────────────────────────────── карта легальных ходов
108	
109	  legalMovesMap() {
110	    const map = {};
111	    if (this.gameOver) return map;
112	    for (const m of this.chess.moves({ verbose: true })) {
113	      (map[m.from] ||= []).push(m.to);
114	    }
115	    for (const k of Object.keys(map)) map[k] = [...new Set(map[k])];
116	    return map;
117	  }
118	
119	  /** Требуется ли выбор фигуры превращения для этого хода. */
120	  needsPromotion(from, to) {
121	    return this.chess
122	      .moves({ verbose: true })
123	      .some((m) => m.from === from && m.to === to && m.flags.includes('p'));
124	  }
125	
126	  // ───────────────────────────────────────────────── ходы
127	
128	  move({ from, to, promotion }) {
129	    if (this.gameOver) return { ok: false, code: 'GAME_OVER', message: 'ПАРТИЯ ОКОНЧЕНА' };
130	    if (this.phase === 'dropping') {
131	      return { ok: false, code: 'DROP_IN_PROGRESS', message: 'ИДЁТ ВЫСАДКА — ПОДОЖДИТЕ' };
132	    }
133	    if (!promotion && this.needsPromotion(from, to)) {
134	      return { ok: false, code: 'PROMOTION_REQUIRED', message: 'ВЫБЕРИТЕ ФИГУРУ ПРЕВРАЩЕНИЯ' };
135	    }
136	
137	    let made;
138	    try {
139	      made = this.chess.move({ from, to, promotion: promotion || undefined });
140	    } catch {
141	      made = null;
142	    }
143	    if (!made) return { ok: false, code: 'ILLEGAL_MOVE', message: 'ТАКОЙ ХОД НЕВОЗМОЖЕН' };
144	
145	    this.#applyPieceMove(made);
146	
147	    this.atoms.push({ kind: 'move', san: made.san, from: made.from, to: made.to, promotion: made.promotion });
148	    this.snapshots.push(this.chess.fen());
149	    this.moveLog.push({
150	      ply: this.moveLog.length + 1,
151	      n: Math.floor(this.moveLog.length / 2) + 1,
152	      color: made.color,
153	      san: made.san,
154	      from: made.from,
155	      to: made.to,
156	      promotion: made.promotion || null,
157	      captured: made.captured || null,
158	      fenAfter: this.chess.fen(),
159	    });
160	    // Счётчик авто-десанта считает ПОЛНЫЕ ходы: подкрепление приходит после хода чёрных,
161	    // иначе одна из сторон систематически получала бы его первой.
162	    if (made.color === 'b') this.movesSinceDrop += 1;
163	    this.version += 1;
164	    this.#refreshGameOver();
165	    return { ok: true, move: made, version: this.version };
166	  }
167	
168	  /**
169	   * Обновление идентификаторов фигур. Их нельзя вычислить сравнением позиций «до»
170	   * и «после»: две одинаковые фигуры на соседних полях неразличимы. Поэтому
171	   * применяем семантику самого хода — по этим идентификаторам клиент анимирует
172	   * перемещение, а не перерисовку.
173	   */
174	  #applyPieceMove(m) {
175	    const moving = this.pieces.get(m.from);
176	    this.pieces.delete(m.from);
177	
178	    if (m.flags.includes('e')) {
179	      // Взятие на проходе: побитая пешка стоит не на поле назначения.
180	      const capturedSquare = `${m.to[0]}${m.color === 'w' ? Number(m.to[1]) - 1 : Number(m.to[1]) + 1}`;
181	      this.pieces.delete(capturedSquare);
182	    } else if (m.captured) {
183	      this.pieces.delete(m.to);
184	    }
185	
186	    if (moving) {
187	      this.pieces.set(m.to, { ...moving, type: m.promotion || moving.type });
188	    }
189	
190	    if (m.flags.includes('k') || m.flags.includes('q')) {
191	      const rank = m.color === 'w' ? '1' : '8';
192	      const [rookFrom, rookTo] = m.flags.includes('k') ? [`h${rank}`, `f${rank}`] : [`a${rank}`, `d${rank}`];
193	      const rook = this.pieces.get(rookFrom);
194	      this.pieces.delete(rookFrom);
195	      if (rook) this.pieces.set(rookTo, rook);
196	    }
197	  }
198	
199	  // ───────────────────────────────────────────────── десант
200	
201	  /** Результат генератора применяется к позиции целиком. */
202	  applyDrop(drop) {
203	    if (!drop || !drop.ok) return { ok: false, code: 'DROP_FAILED', message: 'ВЫСАДКА НЕ СОСТОЯЛАСЬ' };
204	
205	    // Позиция пересобирается из FEN, и вместе с ней в chess.js обнуляется его
206	    // собственная история. Наш журнал атомов от этого не страдает — в этом и смысл.
207	    this.chess.load(drop.fen);
208	
209	    const landed = [];
210	    for (const p of drop.placements) {
211	      const sq = p.squareName || squareName(p.square);
212	      const entry = { id: `p${nextPieceId++}`, type: p.type, color: p.color };
213	      this.pieces.set(sq, entry);
214	      landed.push({ ...entry, square: sq });
215	    }
216	
217	    this.ledgerCp += drop.nominalDeltaCp || 0;
218	    this.movesSinceDrop = 0;
219	    this.consecutiveSkips = 0;
220	
221	    const record = {
222	      id: this.dropLog.length + 1,
223	      afterPly: this.moveLog.length,
224	      atMove: Math.floor(this.moveLog.length / 2) + 1,
225	      trigger: drop.dice ? 'dice' : 'auto',
226	      dice: drop.dice || null,
227	      storyteller: drop.storyteller,
228	      white: landed.filter((p) => p.color === 'w').map((p) => ({ type: p.type, square: p.square })),
229	      black: landed.filter((p) => p.color === 'b').map((p) => ({ type: p.type, square: p.square })),
230	      evalBefore: drop.evalBefore,
231	      evalAfter: drop.evalAfter,
232	      delta: drop.delta,
233	      targetDelta: drop.targetDelta,
234	      error: drop.error,
235	      toleranceUsed: drop.toleranceUsed,
236	      toleranceWidened: drop.toleranceWidened,
237	      searchMs: drop.searchMs,
238	      packageLabel: drop.package ? drop.package.label : null,
239	      ledgerCp: this.ledgerCp,
240	    };
241	    this.dropLog.push(record);
242	    this.atoms.push({ kind: 'drop', dropId: record.id, placements: landed });
243	    this.snapshots.push(this.chess.fen());
244	    this.version += 1;
245	    this.#refreshGameOver();
246	    return { ok: true, drop: record, version: this.version };
247	  }
248	
249	  noteSkippedDrop(reason) {
250	    this.consecutiveSkips += 1;
251	    this.movesSinceDrop = 0; // счётчик перевзводится, чтобы не долбиться каждый ход
252	    this.version += 1;
253	    return { ok: true, reason, version: this.version };
254	  }
255	
256	  spendDiceRoll(side) {
257	    if (this.dice[side] <= 0) return false;
258	    this.dice[side] -= 1;
259	    return true;
260	  }
261	
262	  refundDiceRoll(side) {
263	    this.dice[side] = Math.min(this.settings.diceRollsPerPlayer, this.dice[side] + 1);
264	  }
265	
266	  // ───────────────────────────────────────────────── отмена
267	
268	  /**
269	   * Откат одного атома. Десант откатывается целиком, вместе с записью в журнале
270	   * и возвратом потраченного жетона — иначе отмена дарила бы бросок.
271	   */
272	  undo() {
273	    if (this.atoms.length === 0) {
274	      return { ok: false, code: 'NOTHING_TO_UNDO', message: 'ОТМЕНЯТЬ НЕЧЕГО' };
275	    }
276	    const atom = this.atoms.pop();
277	    this.snapshots.pop();
278	    const restored = this.snapshots[this.snapshots.length - 1];
279	
280	    if (atom.kind === 'move') {
281	      this.moveLog.pop();
282	      if (atom.color === 'b' || this.chess.turn() === 'w') this.movesSinceDrop = Math.max(0, this.movesSinceDrop - 1);
283	    } else {
284	      const record = this.dropLog.pop();
285	      if (record) {
286	        this.ledgerCp -= record.ledgerCp - (this.dropLog[this.dropLog.length - 1]?.ledgerCp || 0);
287	        if (record.trigger === 'dice' && record.dice) this.refundDiceRoll(record.dice.side);
288	      }
289	    }
290	
291	    this.chess.load(restored);
292	    this.#rebuildPieceIds();
293	    this.version += 1;
294	    this.#refreshGameOver();
295	    return { ok: true, version: this.version };
296	  }
297	
298	  /**
299	   * После отката идентификаторы фигур приходится назначать заново: восстановить,
300	   * какой именно конь стоял на поле три хода назад, из FEN невозможно. Для анимации
301	   * это означает разовую перерисовку доски, что честнее, чем притворяться.
302	   */
303	  #rebuildPieceIds() {
304	    this.pieces = new Map();
305	    for (const sq of this.#occupiedSquares()) {
306	      const p = this.chess.get(sq);
307	      this.pieces.set(sq, { id: `p${nextPieceId++}`, type: p.type, color: p.color });
308	    }
309	  }
310	
311	  // ───────────────────────────────────────────────── конец партии
312	
313	  #refreshGameOver() {
314	    if (this.chess.isCheckmate()) {
315	      const winner = this.chess.turn() === 'w' ? 'b' : 'w';
316	      this.gameOver = {
317	        reason: 'checkmate',
318	        winner,
319	        text: `${GAME_OVER_TEXT.checkmate}. ПОБЕДА ${winner === 'w' ? 'МОРПЕХОВ' : 'КСЕНО'}.`,
320	      };
321	    } else if (this.chess.isStalemate()) {
322	      this.gameOver = { reason: 'stalemate', winner: null, text: GAME_OVER_TEXT.stalemate };
323	    } else if (this.chess.isInsufficientMaterial()) {
324	      this.gameOver = { reason: 'insufficient_material', winner: null, text: GAME_OVER_TEXT.insufficient_material };
325	    } else if (this.chess.isThreefoldRepetition()) {
326	      this.gameOver = { reason: 'threefold', winner: null, text: GAME_OVER_TEXT.threefold };
327	    } else if (this.chess.isDrawByFiftyMoves()) {
328	      this.gameOver = { reason: 'fifty_move', winner: null, text: GAME_OVER_TEXT.fifty_move };
329	    } else {
330	      this.gameOver = null;
331	    }
332	    this.phase = this.gameOver ? 'over' : this.phase === 'dropping' ? 'dropping' : 'idle';
333	  }
334	
335	  // ───────────────────────────────────────────────── снимок для клиента
336	
337	  snapshot(extra = {}) {
338	    const board = [];
339	    for (const [square, piece] of this.pieces) {
340	      board.push({ square, id: piece.id, type: piece.type, color: piece.color });
341	    }
342	    const { total } = countMaterial(this.fen);
343	    return {
344	      version: this.version,
345	      phase: this.phase,
346	      fen: this.fen,
347	      turn: this.turn,
348	      inCheck: this.chess.isCheck(),
349	      board,
350	      legalMoves: this.legalMovesMap(),
351	      gameOver: this.gameOver,
352	      moveLog: this.moveLog,
353	      dropLog: this.dropLog,
354	      dice: this.dice,
355	      movesUntilAutoDrop: this.movesUntilAutoDrop,
356	      ledgerCp: this.ledgerCp,
357	      materialCp: materialBalance(this.fen),
358	      pieceCount: total,
359	      freeSlots: freeSlots(this.fen),
360	      settings: this.settings,
361	      storyteller: {
362	        id: this.storyteller.id,
363	        name: this.storyteller.name,
364	        codename: this.storyteller.codename,
365	        blurb: this.storyteller.blurb,
366	        toleranceCp: this.storyteller.toleranceCp,
367	      },
368	      lastDrop: this.dropLog[this.dropLog.length - 1] || null,
369	      ...extra,
370	    };
371	  }
372	
373	  /** PGN с десантами в виде комментариев — партию должно быть можно перечитать. */
374	  toPgn() {
375	    const lines = [];
376	    let moveNo = 1;
377	    let buffer = '';
378	    for (const atom of this.atoms) {
379	      if (atom.kind === 'move') {
380	        if (buffer === '') buffer = `${moveNo}. ${atom.san}`;
381	        else {
382	          lines.push(`${buffer} ${atom.san}`);
383	          buffer = '';
384	          moveNo += 1;
385	        }
386	      } else {
387	        const rec = this.dropLog.find((d) => d.id === atom.dropId);
388	        const desc = atom.placements.map((p) => `${p.color}${p.type}${p.square}`).join(' ');
389	        const note = `{ ДЕСАНТ #${atom.dropId}: ${desc}${rec ? ` (Δ ${rec.delta} сп)` : ''} }`;
390	        if (buffer) {
391	          lines.push(`${buffer} ${note}`);
392	          buffer = '';
393	        } else lines.push(note);
394	      }
395	    }
396	    if (buffer) lines.push(buffer);
397	    return lines.join('\n');
398	  }
399	}
