1	// Детерминированный генератор. Не Math.random: и тесты, и ночной прогон обязаны
2	// воспроизводиться по сиду, иначе ни один упавший десант не удастся разобрать.
3	// xorshift128+ — быстрый, с приличным периодом и без внешних зависимостей.
4	
5	function hashSeed(seed) {
6	  const s = String(seed);
7	  let h1 = 0x9e3779b9;
8	  let h2 = 0x85ebca6b;
9	  for (let i = 0; i < s.length; i++) {
10	    const c = s.charCodeAt(i);
11	    h1 = Math.imul(h1 ^ c, 2654435761) >>> 0;
12	    h2 = Math.imul(h2 ^ ((c << 3) | (c >>> 5)), 1597334677) >>> 0;
13	  }
14	  // Нулевое состояние для xorshift — вырожденное, страхуемся.
15	  return [h1 || 0x1a2b3c4d, h2 || 0x5e6f7a8b, (h1 ^ h2) >>> 0 || 0xdeadbeef, (h1 + h2) >>> 0 || 0xfeedface];
16	}
17	
18	export class Rng {
19	  constructor(seed = 'nostromo') {
20	    this.seed = String(seed);
21	    const [a, b, c, d] = hashSeed(seed);
22	    this.s = new Uint32Array([a, b, c, d]);
23	    // Прокручиваем, чтобы близкие сиды не давали похожих первых чисел.
24	    for (let i = 0; i < 20; i++) this.next();
25	  }
26	
27	  /** Целое 32 бита. */
28	  next() {
29	    let t = this.s[3];
30	    const s0 = this.s[0];
31	    this.s[3] = this.s[2];
32	    this.s[2] = this.s[1];
33	    this.s[1] = s0;
34	    t ^= t << 11;
35	    t ^= t >>> 8;
36	    this.s[0] = (t ^ s0 ^ (s0 >>> 19)) >>> 0;
37	    return this.s[0];
38	  }
39	
40	  /** [0, 1) */
41	  float() {
42	    return this.next() / 4294967296;
43	  }
44	
45	  /** Целое из [min, max] включительно. */
46	  int(min, max) {
47	    if (max < min) return min;
48	    return min + (this.next() % (max - min + 1));
49	  }
50	
51	  /** Один элемент массива. */
52	  pick(arr) {
53	    if (!arr || arr.length === 0) return undefined;
54	    return arr[this.next() % arr.length];
55	  }
56	
57	  /** Перемешивание на месте (Фишер—Йетс). */
58	  shuffle(arr) {
59	    for (let i = arr.length - 1; i > 0; i--) {
60	      const j = this.next() % (i + 1);
61	      [arr[i], arr[j]] = [arr[j], arr[i]];
62	    }
63	    return arr;
64	  }
65	
66	  /** Выбор по весам: items — [{weight, ...}]. */
67	  weighted(items, weightOf = (x) => x.weight) {
68	    const total = items.reduce((s, x) => s + Math.max(0, weightOf(x)), 0);
69	    if (total <= 0) return this.pick(items);
70	    let roll = this.float() * total;
71	    for (const item of items) {
72	      roll -= Math.max(0, weightOf(item));
73	      if (roll <= 0) return item;
74	    }
75	    return items[items.length - 1];
76	  }
77	
78	  /** Отдельный поток случайности, привязанный к метке — чтобы ветки не сдвигали друг друга. */
79	  fork(label) {
80	    return new Rng(`${this.seed}:${label}:${this.next()}`);
81	  }
82	}
83	
84	export function makeRng(seed) {
85	  return new Rng(seed);
86	}
