1	// Кубики: 2d6 задают параметры десанта.
2	//
3	// Замысел в напряжении между двумя числами одного броска:
4	//   сумма    -> тоннаж (сколько материала прилетит обеим сторонам);
5	//   разброс  -> перекос (сколько сантипешек бросающий вправе забрать себе).
6	// Дубль даёт нулевой перекос, но чётную сумму; максимальный перекос (6-1) даёт
7	// всего 7 очков тоннажа. Выкрутить и объём, и наглость одновременно нельзя.
8	
9	/** Жёсткий предел суммарного перекоса, включая собственный люфт планировщика. */
10	export const MAX_TOTAL_SKEW_CP = 120;
11	
12	export const DICE = {
13	  budgetBase: 60,
14	  budgetStep: 90,
15	  skewStep: 20,
16	};
17	
18	export function rollDice(rng) {
19	  return { d1: rng.int(1, 6), d2: rng.int(1, 6) };
20	}
21	
22	/**
23	 * Разбор броска.
24	 * @param {{d1:number,d2:number}} dice
25	 * @param {'w'|'b'} side  кто бросил — в его пользу и уходит перекос
26	 */
27	export function interpretRoll({ d1, d2 }, side) {
28	  const sum = d1 + d2;
29	  const spread = Math.abs(d1 - d2);
30	  const budgetCp = DICE.budgetBase + DICE.budgetStep * (sum - 2);
31	  const magnitude = DICE.skewStep * spread;
32	  // Перекос всегда выражен в POV белых: белым в плюс, чёрным в минус.
33	  const skewCp = side === 'w' ? magnitude : -magnitude;
34	  return {
35	    d1,
36	    d2,
37	    sum,
38	    spread,
39	    budgetCp,
40	    skewCp,
41	    isDouble: spread === 0,
42	    side,
43	  };
44	}
45	
46	/** Суммарная цель по перекосу с учётом люфта планировщика, с жёстким клампом. */
47	export function combineSkew(diceSkewCp, storytellerSkewCp) {
48	  const total = (diceSkewCp || 0) + (storytellerSkewCp || 0);
49	  return Math.max(-MAX_TOTAL_SKEW_CP, Math.min(MAX_TOTAL_SKEW_CP, total));
50	}
51	
52	/** Строка-расшифровка для интерфейса — игрок должен понимать, что ему выпало. */
53	export function describeRoll(roll) {
54	  const dir = roll.skewCp === 0 ? '' : roll.side === 'w' ? ' В ПОЛЬЗУ МОРПЕХОВ' : ' В ПОЛЬЗУ КСЕНО';
55	  const skew = roll.skewCp === 0 ? 'РОВНО' : `${Math.abs(roll.skewCp)} СП${dir}`;
56	  return `СУММА ${roll.sum} → ТОННАЖ ${roll.budgetCp} СП · РАЗБРОС ${roll.spread} → ПЕРЕКОС ${skew}`;
57	}
