1	// Отдача статики из public/.
2	//
3	// Две вещи, на которых обычно спотыкаются: charset в заголовке (без него кириллица
4	// превращается в кракозябры даже при правильном <meta>) и выход за пределы каталога.
5	import fs from 'node:fs/promises';
6	import path from 'node:path';
7	import { createHash } from 'node:crypto';
8	
9	const MIME = {
10	  '.html': 'text/html; charset=utf-8',
11	  '.js': 'text/javascript; charset=utf-8',
12	  '.mjs': 'text/javascript; charset=utf-8',
13	  '.css': 'text/css; charset=utf-8',
14	  '.json': 'application/json; charset=utf-8',
15	  '.svg': 'image/svg+xml; charset=utf-8',
16	  '.png': 'image/png',
17	  '.woff2': 'font/woff2',
18	  '.ico': 'image/x-icon',
19	  '.txt': 'text/plain; charset=utf-8',
20	};
21	
22	export function createStaticHandler(root) {
23	  const rootResolved = path.resolve(root);
24	
25	  return async function serve(req, res, urlPath) {
26	    let rel = decodeURIComponent(urlPath);
27	    if (rel === '/' || rel === '') rel = '/index.html';
28	
29	    // Собираем путь и убеждаемся, что он не вышел из корня. Проверять надо
30	    // ПОСЛЕ разрешения: '/../..' и его закодированные формы иначе проходят.
31	    const target = path.resolve(rootResolved, `.${rel}`);
32	    if (target !== rootResolved && !target.startsWith(rootResolved + path.sep)) {
33	      res.writeHead(400, { 'Content-Type': 'text/plain; charset=utf-8' });
34	      res.end('ВЫХОД ЗА ПРЕДЕЛЫ КАТАЛОГА');
35	      return true;
36	    }
37	
38	    let body;
39	    try {
40	      const stat = await fs.stat(target);
41	      if (stat.isDirectory()) return false;
42	      body = await fs.readFile(target);
43	    } catch {
44	      return false;
45	    }
46	
47	    const etag = `W/"${createHash('sha1').update(body).digest('hex').slice(0, 16)}"`;
48	    if (req.headers['if-none-match'] === etag) {
49	      res.writeHead(304);
50	      res.end();
51	      return true;
52	    }
53	
54	    res.writeHead(200, {
55	      'Content-Type': MIME[path.extname(target).toLowerCase()] || 'application/octet-stream',
56	      'Content-Length': body.length,
57	      ETag: etag,
58	      'Cache-Control': 'no-cache',
59	    });
60	    res.end(req.method === 'HEAD' ? undefined : body);
61	    return true;
62	  };
63	}
