1	#!/usr/bin/env node
2	// Зеркалирование исходников в каталог проекта на диске G:.
3	//
4	// Почему рабочая копия не там: G: — виртуальный том Google Drive. Проверено на месте:
5	// npm install создаёт там файлы НУЛЕВОЙ длины (npm ловит TAR_ENTRY_ERROR и продолжает),
6	// junction'ы не создаются («требуется локальный том NTFS»), а события файловой системы
7	// теряются. Наши собственные записи туда проходят нормально, поэтому исходники зеркалим,
8	// а сборка и запуск живут на C:.
9	import fs from 'node:fs';
10	import path from 'node:path';
11	import { fileURLToPath } from 'node:url';
12	
13	const SRC = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
14	const DST = process.env.NOSTROMO_MIRROR || 'G:\\Другие компьютеры\\PAULEKMAN\\dev\\nostromo-gambit';
15	
16	const SKIP_DIRS = new Set(['node_modules', '.git', 'artifacts']);
17	const SKIP_FILES = new Set(['.DS_Store']);
18	
19	let copied = 0;
20	let skipped = 0;
21	const failures = [];
22	
23	function mirror(relDir = '') {
24	  const from = path.join(SRC, relDir);
25	  const to = path.join(DST, relDir);
26	  fs.mkdirSync(to, { recursive: true });
27	
28	  for (const entry of fs.readdirSync(from, { withFileTypes: true })) {
29	    if (entry.isDirectory()) {
30	      if (SKIP_DIRS.has(entry.name)) continue;
31	      mirror(path.join(relDir, entry.name));
32	      continue;
33	    }
34	    if (SKIP_FILES.has(entry.name)) continue;
35	
36	    const srcFile = path.join(from, entry.name);
37	    const dstFile = path.join(to, entry.name);
38	    const srcStat = fs.statSync(srcFile);
39	    try {
40	      const dstStat = fs.statSync(dstFile);
41	      if (dstStat.size === srcStat.size && dstStat.mtimeMs >= srcStat.mtimeMs) {
42	        skipped += 1;
43	        continue;
44	      }
45	    } catch {
46	      /* назначения ещё нет — копируем */
47	    }
48	    try {
49	      fs.copyFileSync(srcFile, dstFile);
50	      // Диск синхронизируемый: убеждаемся, что файл долетел целиком, а не нулевым.
51	      const check = fs.statSync(dstFile);
52	      if (check.size !== srcStat.size) throw new Error(`размер не совпал: ${check.size} вместо ${srcStat.size}`);
53	      copied += 1;
54	    } catch (err) {
55	      failures.push(`${path.join(relDir, entry.name)}: ${err.message}`);
56	    }
57	  }
58	}
59	
60	mirror();
61	
62	console.log(`зеркало -> ${DST}`);
63	console.log(`  скопировано: ${copied}, без изменений: ${skipped}`);
64	if (failures.length) {
65	  console.warn(`  НЕ УДАЛОСЬ (${failures.length}):`);
66	  for (const f of failures.slice(0, 20)) console.warn(`    ${f}`);
67	  process.exit(1);
68	}
