1	// Все рантайм-артефакты живут в %LOCALAPPDATA%, а не рядом с исходниками.
2	// Причина зафиксирована в плане: каталог проекта пользователя лежит на виртуальном
3	// диске Google Drive, где npm-распаковка даёт файлы нулевой длины, junction'ы
4	// не создаются, а событий файловой системы можно не дождаться.
5	import os from 'node:os';
6	import path from 'node:path';
7	import fs from 'node:fs';
8	
9	const APP = 'nostromo-gambit';
10	
11	function baseDir() {
12	  if (process.env.NOSTROMO_HOME) return path.resolve(process.env.NOSTROMO_HOME);
13	  const local =
14	    process.env.LOCALAPPDATA ||
15	    (process.platform === 'darwin'
16	      ? path.join(os.homedir(), 'Library', 'Application Support')
17	      : path.join(os.homedir(), '.local', 'share'));
18	  return path.join(local, APP);
19	}
20	
21	export const ROOT = baseDir();
22	export const ENGINE_DIR = path.join(ROOT, 'engine');
23	export const DOWNLOAD_DIR = path.join(ROOT, 'downloads');
24	export const SELFPLAY_DIR = path.join(ROOT, 'selfplay');
25	export const CURRENT_JSON = path.join(ENGINE_DIR, 'current.json');
26	export const RELEASE_CACHE = path.join(ROOT, 'release-cache.json');
27	export const SESSION_FILE = path.join(ROOT, 'session.json');
28	
29	/**
30	 * Реестр PID'ов — файл НА КАЖДЫЙ процесс-владелец, а не один общий.
31	 * Общий файл — это read-modify-write из нескольких процессов без блокировки:
32	 * сервер, ночной прогон и параллельные тестовые файлы затирали бы записи друг друга,
33	 * и в реестре оставались бы призраки, которых потом кто-то попытается отстрелить.
34	 */
35	export const PID_REGISTRY_PREFIX = 'engines.';
36	export const PID_REGISTRY_SUFFIX = '.pid';
37	export function pidRegistryFile(ownerPid = process.pid) {
38	  return path.join(ROOT, `${PID_REGISTRY_PREFIX}${ownerPid}${PID_REGISTRY_SUFFIX}`);
39	}
40	export function listPidRegistryFiles() {
41	  try {
42	    return fs
43	      .readdirSync(ROOT)
44	      .filter((f) => f.startsWith(PID_REGISTRY_PREFIX) && f.endsWith(PID_REGISTRY_SUFFIX))
45	      .map((f) => ({
46	        file: path.join(ROOT, f),
47	        owner: Number(f.slice(PID_REGISTRY_PREFIX.length, -PID_REGISTRY_SUFFIX.length)),
48	      }))
49	      .filter((e) => Number.isFinite(e.owner));
50	  } catch {
51	    return [];
52	  }
53	}
54	
55	export function ensureDirs() {
56	  for (const d of [ROOT, ENGINE_DIR, DOWNLOAD_DIR, SELFPLAY_DIR]) {
57	    fs.mkdirSync(d, { recursive: true });
58	  }
59	  return ROOT;
60	}
61	
62	/** Атомарная запись: пишем во временный файл рядом, потом переименовываем. */
63	export function writeJsonAtomic(file, obj) {
64	  fs.mkdirSync(path.dirname(file), { recursive: true });
65	  const tmp = `${file}.${process.pid}.tmp`;
66	  fs.writeFileSync(tmp, JSON.stringify(obj, null, 2), 'utf8');
67	  fs.renameSync(tmp, file);
68	}
69	
70	export function readJsonSafe(file, fallback = null) {
71	  try {
72	    return JSON.parse(fs.readFileSync(file, 'utf8'));
73	  } catch {
74	    return fallback;
75	  }
76	}
