1	// Таблица наборов десанта.
2	//
3	// Наборы намеренно АСИММЕТРИЧНЫ по составу: пешка со слоном против ладьи — это то,
4	// ради чего игра затевалась. Номинальная стоимость сторон при этом близка, но не
5	// равна: остаток разницы добирается выбором полей, а не подгонкой состава.
6	import { PIECE_VALUE, countMaterial, freeSlots, promotionDebt, LIMITS } from './fen.mjs';
7	
8	/** Один вход таблицы: что получают белые и что чёрные. */
9	const RAW_TABLE = [
10	  // Малый тоннаж
11	  { w: ['p'], b: ['p'] },
12	  { w: ['p', 'p'], b: ['p', 'p'] },
13	  { w: ['p', 'p'], b: ['p'] },
14	  { w: ['n'], b: ['p', 'p', 'p'] },
15	  { w: ['b'], b: ['p', 'p', 'p'] },
16	  { w: ['n'], b: ['b'] },
17	  { w: ['n'], b: ['n'] },
18	  { w: ['b'], b: ['b'] },
19	  { w: ['b', 'p'], b: ['n', 'p'] },
20	
21	  // Средний тоннаж
22	  { w: ['b', 'p'], b: ['r'] },
23	  { w: ['n', 'p'], b: ['r'] },
24	  { w: ['r'], b: ['n', 'p', 'p'] },
25	  { w: ['r'], b: ['b', 'p', 'p'] },
26	  { w: ['r'], b: ['r'] },
27	  { w: ['n', 'n'], b: ['r', 'p'] },
28	  { w: ['b', 'b'], b: ['r', 'p'] },
29	  { w: ['n', 'b'], b: ['r', 'p', 'p'] },
30	  { w: ['r', 'p'], b: ['n', 'b'] },
31	
32	  // Крупный тоннаж
33	  { w: ['q'], b: ['r', 'r'] },
34	  { w: ['q'], b: ['r', 'n', 'p'] },
35	  { w: ['q'], b: ['r', 'b', 'p'] },
36	  { w: ['r', 'r'], b: ['q', 'p'] },
37	  { w: ['q', 'p'], b: ['r', 'r'] },
38	  { w: ['b', 'n', 'p'], b: ['r', 'n'] },
39	  { w: ['r', 'b'], b: ['q'] },
40	  { w: ['r', 'n', 'p'], b: ['q', 'p'] },
41	];
42	
43	export function valueOf(list) {
44	  return list.reduce((s, t) => s + PIECE_VALUE[t], 0);
45	}
46	
47	/** Тоннаж набора — по более тяжёлой стороне: это то, что видно на доске. */
48	export function tonnageOf(pkg) {
49	  return Math.max(valueOf(pkg.w), valueOf(pkg.b));
50	}
51	
52	/** Номинальный перекос набора в POV белых. Идёт в материальный гроссбух. */
53	export function nominalDelta(pkg) {
54	  return valueOf(pkg.w) - valueOf(pkg.b);
55	}
56	
57	export function packageSize(pkg) {
58	  return pkg.w.length + pkg.b.length;
59	}
60	
61	/** Оба направления каждой строки таблицы: набор «Ф против 2Л» работает в обе стороны. */
62	function expand(table) {
63	  const out = [];
64	  for (const row of table) {
65	    out.push({ w: [...row.w], b: [...row.b] });
66	    const key = (p) => p.join('');
67	    if (key(row.w) !== key(row.b)) out.push({ w: [...row.b], b: [...row.w] });
68	  }
69	  return out.map((pkg, i) => ({ ...pkg, id: i, tonnage: tonnageOf(pkg), delta: nominalDelta(pkg) }));
70	}
71	
72	export const PACKAGES = expand(RAW_TABLE);
73	
74	/**
75	 * Влезает ли набор в позицию, не ломая пределов.
76	 * Отдельная функция, потому что проверять надо ДО поиска полей: нет смысла считать
77	 * маржинальную таблицу для набора, который всё равно нельзя применить.
78	 */
79	export function packageFits(fen, pkg, limits = LIMITS) {
80	  const { counts, total } = countMaterial(fen);
81	  if (total + packageSize(pkg) > limits.totalPieces) return false;
82	
83	  for (const color of ['w', 'b']) {
84	    const add = pkg[color];
85	    const side = { ...counts[color] };
86	    for (const t of add) side[t] += 1;
87	    const sideTotal = Object.values(side).reduce((s, n) => s + n, 0);
88	    if (side.p > limits.pawnsPerSide) return false;
89	    if (side.q > limits.queensPerSide) return false;
90	    if (sideTotal > limits.piecesPerSide) return false;
91	    // Сверхкомплектные фигуры требуют превращённых пешек — иначе позиция недостижима
92	    // и Stockfish на ней завершается.
93	    if (side.p + promotionDebt(side) > limits.pawnsPerSide) return false;
94	  }
95	  return true;
96	}
