98	/**
99	 * Выбор набора под заданный тоннаж.
100	 *
101	 * Учитывается три вещи сверх самого тоннажа:
102	 *  - теснота: чем меньше пустых полей, тем сильнее сдвиг к мелким наборам,
103	 *    иначе доска за десяток десантов превращается в кашу и упирается в предел 32;
104	 *  - гроссбух: накопленный номинальный перекос гасится выбором набора в другую сторону,
105	 *    потому что «ноль по оценке» и «поровну материала» — это разные вещи, и вторую
106	 *    люди замечают глазами;
107	 *  - предпочтение асимметрии: симметричные наборы допустимы, но это не то, ради чего игра.
108	 */
109	export function samplePackage(rng, { fen, budgetCp = 400, ledgerCp = 0, limits = LIMITS, exclude = [] } = {}) {
110	  // Ограничивает десант число СВОБОДНЫХ СЛОТОВ, а не пустых полей: в начальной
111	  // позиции пустых полей 32, а добавить нельзя ни одной фигуры.
112	  const roomForPieces = freeSlots(fen, limits);
113	  if (roomForPieces < 2) return null; // минимальный десант — по фигуре каждой стороне
114	
115	  // Чем меньше слотов, тем мельче наборы: иначе первый же крупный десант забьёт
116	  // доску под потолок и следующие станут невозможны.
117	  const roominess = Math.min(1, roomForPieces / 10);
118	  const effectiveBudget = Math.max(100, Math.round(budgetCp * (0.45 + 0.55 * roominess)));
119	
120	  const excluded = new Set(exclude);
121	  const candidates = PACKAGES.filter(
122	    (pkg) => !excluded.has(pkg.id) && packageSize(pkg) <= roomForPieces && packageFits(fen, pkg, limits),
123	  );
124	  if (candidates.length === 0) return null;
125	
126	  const scored = candidates.map((pkg) => {
127	    // Близость к бюджету — основной вес.
128	    const distance = Math.abs(pkg.tonnage - effectiveBudget);
129	    let weight = 1 / (1 + (distance / 220) ** 2);
130	    // Гроссбух: если белым уже выдали больше, награждаем наборы в пользу чёрных.
131	    if (ledgerCp !== 0) {
132	      const corrective = -Math.sign(ledgerCp) * Math.sign(pkg.delta || 0);
133	      const strength = Math.min(1, Math.abs(ledgerCp) / 300);
134	      weight *= 1 + corrective * strength * 0.9;
135	    }
136	    // Асимметрия состава — то, ради чего механика существует.
137	    if (pkg.w.length !== pkg.b.length) weight *= 1.45;
138	    return { pkg, weight: Math.max(0.001, weight) };
139	  });
140	
141	  const chosen = rng.weighted(scored, (x) => x.weight);
142	  return chosen ? chosen.pkg : null;
143	}
144	
145	/**
146	 * Ремонт набора вместо полной пересборки: если по оценке не хватило совсем немного,
147	 * дешевле подправить состав, чем считать всё заново — маржинальная таблица уже готова
148	 * и переиспользуется целиком.
149	 *
150	 * @param {'w'|'b'} side  кому добавить веса
151	 */
152	export function repairPackage(pkg, side, { fen, limits = LIMITS } = {}) {
153	  const other = side === 'w' ? 'b' : 'w';
154	
155	  // Вариант 1: добавить недобирающей стороне лёгкую фигуру.
156	  // Пешка — первый выбор, но она не всегда влезает: у стороны может быть все восемь,
157	  // и тогда девятая делает позицию недостижимой. Раньше на этом ступень лестницы
158	  // просто пропадала, поэтому перебираем варианты по возрастанию веса.
159	  for (const type of ['p', 'n', 'b', 'r']) {
160	    const grown = { ...pkg, w: [...pkg.w], b: [...pkg.b] };
161	    grown[side] = [...grown[side], type];
162	    if (!fen || packageFits(fen, grown, limits)) {
163	      return { ...grown, id: `${pkg.id}+${type}${side}`, tonnage: tonnageOf(grown), delta: nominalDelta(grown) };
164	    }
165	  }
166	
167	  // Вариант 2: разменять коня противоположной стороны на три пешки — тот же тоннаж,
168	  // но совсем другая позиция, и часто этого хватает, чтобы сойтись по оценке.
169	  const idx = pkg[other].indexOf('n');
170	  if (idx >= 0) {
171	    const swapped = { ...pkg, w: [...pkg.w], b: [...pkg.b] };
172	    swapped[other] = [...swapped[other]];
173	    swapped[other].splice(idx, 1, 'p', 'p', 'p');
174	    if (!fen || packageFits(fen, swapped, limits)) {
175	      return { ...swapped, id: `${pkg.id}~n${other}`, tonnage: tonnageOf(swapped), delta: nominalDelta(swapped) };
176	    }
177	  }
178	  return null;
179	}
180	
181	/** Человеческое имя набора для журнала: «▲ Слон + пешка против ладьи». */
182	const RU_PIECE = { p: 'пешка', n: 'конь', b: 'слон', r: 'ладья', q: 'ферзь' };
183	export function describePackage(pkg) {
184	  const side = (list) => list.map((t) => RU_PIECE[t]).join(' + ');
185	  return `${side(pkg.w)} против ${side(pkg.b)}`;
186	}
