46	/**
47	 * Клиент потока событий: читает SSE напрямую из fetch-потока.
48	 * EventSource в Node есть, но собственный разбор даёт доступ к сырым кадрам,
49	 * а именно их формат мы и проверяем.
50	 */
51	export async function openStream(base, { lastEventId = null } = {}) {
52	  const headers = { Accept: 'text/event-stream' };
53	  if (lastEventId !== null) headers['Last-Event-ID'] = String(lastEventId);
54	  const controller = new AbortController();
55	  const res = await fetch(`${base}/api/events`, { headers, signal: controller.signal });
56	
57	  const events = [];
58	  const waiters = [];
59	  const reader = res.body.getReader();
60	  const decoder = new TextDecoder();
61	  let buffer = '';
62	
63	  (async () => {
64	    try {
65	      for (;;) {
66	        const { done, value } = await reader.read();
67	        if (done) break;
68	        buffer += decoder.decode(value, { stream: true });
69	        let sep;
70	        while ((sep = buffer.indexOf('\n\n')) >= 0) {
71	          const raw = buffer.slice(0, sep);
72	          buffer = buffer.slice(sep + 2);
73	          const frame = { id: null, event: 'message', data: '' };
74	          for (const line of raw.split('\n')) {
75	            if (line.startsWith('id: ')) frame.id = Number(line.slice(4));
76	            else if (line.startsWith('event: ')) frame.event = line.slice(7);
77	            else if (line.startsWith('data: ')) frame.data += line.slice(6);
78	          }
79	          if (frame.event === 'message' && !frame.data) continue; // heartbeat
80	          try {
81	            frame.json = JSON.parse(frame.data);
82	          } catch {
83	            frame.json = null;
84	          }
85	          events.push(frame);
86	          for (const w of waiters.slice()) {
87	            if (w.test(frame)) {
88	              waiters.splice(waiters.indexOf(w), 1);
89	              w.resolve(frame);
90	            }
91	          }
92	        }
93	      }
94	    } catch {
95	      /* поток закрыт — это штатное завершение */
96	    }
97	  })();
98	
99	  return {
100	    events,
101	    headers: res.headers,
102	    /** Дождаться кадра, удовлетворяющего условию (или уже пришедшего). */
103	    waitFor(test, timeoutMs = 4000) {
104	      const hit = events.find(test);
105	      if (hit) return Promise.resolve(hit);
106	      return new Promise((resolve, reject) => {
107	        const w = { test, resolve };
108	        waiters.push(w);
109	        setTimeout(() => {
110	          const i = waiters.indexOf(w);
111	          if (i >= 0) {
112	            waiters.splice(i, 1);
113	            reject(new Error('не дождались кадра за отведённое время'));
114	          }
115	        }, timeoutMs);
116	      });
117	    },
118	    close() {
119	      controller.abort();
120	    },
121	  };
122	}
